      {showTemplates && <div className="grid items-start gap-5 lg:grid-cols-2"><form className={`${card} space-y-4`} onSubmit={async (event) => { event.preventDefault(); const result = await act("templates", template, "Template saved.", template.id ? "PATCH" : "POST"); if (result) setTemplate({ id: "", name: "", channel, subject: "", body: "" }) }}><h2 className="text-lg font-semibold">{template.id ? "Edit template" : "Create a template"}</h2><input aria-label="Template name" required maxLength={120} placeholder="Template name" className={input} value={template.name} onChange={(event) => setTemplate({ ...template, name: event.target.value })} />{template.channel === "email" && <input aria-label="Template subject" placeholder="Email subject" required className={input} value={template.subject} onChange={(event) => setTemplate({ ...template, subject: event.target.value })} />}<textarea aria-label="Template message" required rows={8} maxLength={template.channel === "sms" ? 480 : template.channel === "whatsapp" ? 2000 : 20000} className={input} value={template.body} onChange={(event) => setTemplate({ ...template, body: event.target.value })} /><p className="text-xs text-slate-500">Use {"{{name}}"}, {"{{business}}"}, {"{{product}}"}. Email signatures are added automatically.</p><Button disabled={busy}><Plus className="h-4 w-4" />Save template</Button></form><div className="space-y-3">{workspace.templates.filter((item) => item.channel === channel).map((item) => <article key={item.id} className={card}><p className="text-xs uppercase tracking-wide text-blue-600">{item.channel}</p><h3 className="mt-1 font-semibold">{item.name}</h3><p className="mt-2 text-sm text-slate-600">{item.subject}</p><p className="mt-2 whitespace-pre-wrap text-xs leading-5 text-slate-500">{item.body}</p><button type="button" onClick={() => setTemplate({ ...item })} className="mt-3 text-sm font-medium text-blue-700 underline">Edit template</button></article>)}</div></div>}
